// Tiles generated by code: each is a shape in hex-local unit space (a signed-distance function, open
// where < 0) from one of a few families. Its 18 sockets (3 per side) are the shape sampled at the
// segment midpoints. Tiles with the same sockets are duplicates: the first shape wins.

import { SOCKET } from './hex.js'

export const CLASSES = ['solid', 'open', 'wall', 'passage', 'junction', 'pocket']
export const SOLID = 0
export const OPEN = 1
export const WALL = 2
export const PASSAGE = 3
export const JUNCTION = 4
export const POCKET = 5

/**
 * @typedef {object} Tile
 * @property {number} id
 * @property {number} cls index into CLASSES
 * @property {number} sockets 18 bits, bit 3k+j = segment j of side k is open
 * @property {(x: number, y: number) => number} sdf open where < 0
 * @property {number[]} sides passages and junctions: the sides their arms leave by
 * @property {number} angle walls: the boundary's angle index (0–11), else -1
 */

const HALF = 0.2 // half a passage's thickness: about one segment (1/3 of a side) thick
const MIN_ANGLE = (55 * Math.PI) / 180 // two arms closer than this are a near U-turn: dropped

/** @param {number} px @param {number} py @param {number} ax @param {number} ay */
function toCentre(px, py, ax, ay) {
  // distance from p to the segment from a to the centre (0, 0)
  const t = Math.max(0, Math.min(1, (px * -ax + py * -ay + ax * ax + ay * ay) / (ax * ax + ay * ay)))
  const x = ax - ax * t - px
  const y = ay - ay * t - py
  return Math.sqrt(x * x + y * y)
}

/** @param {number} a @param {number} b */
function armAngle(a, b) {
  const [ax, ay] = SOCKET[a]
  const [bx, by] = SOCKET[b]
  return Math.acos((ax * bx + ay * by) / Math.hypot(ax, ay) / Math.hypot(bx, by))
}

/** @param {number[]} arms socket ids @returns {(x: number, y: number) => number} */
function armsSdf(arms) {
  const pts = arms.map((s) => SOCKET[s])
  return (x, y) => {
    let d = arms.length > 2 ? Math.hypot(x, y) - HALF * 1.4 : Infinity
    for (const [ax, ay] of pts) d = Math.min(d, toCentre(x, y, ax, ay) - HALF)
    return d
  }
}

/** @returns {Tile[]} */
export function makeTiles() {
  /** @type {{cls: number, sdf: (x: number, y: number) => number, sides?: number[], angle?: number}[]} */
  const shapes = []
  shapes.push({ cls: SOLID, sdf: () => 1 })
  shapes.push({ cls: OPEN, sdf: () => -1 })
  for (let a = 0; a < 12; a++) {
    const nx = Math.cos((a * Math.PI) / 6)
    const ny = Math.sin((a * Math.PI) / 6)
    for (const off of [0, -0.5, 0.5]) shapes.push({ cls: WALL, sdf: (x, y) => nx * x + ny * y - off, angle: a })
  }
  for (let a = 0; a < 18; a++)
    for (let b = a + 1; b < 18; b++) {
      if (Math.floor(a / 3) === Math.floor(b / 3) || armAngle(a, b) < MIN_ANGLE) continue
      shapes.push({ cls: PASSAGE, sdf: armsSdf([a, b]), sides: [Math.floor(a / 3), Math.floor(b / 3)] })
    }
  for (let a = 0; a < 18; a++)
    for (let b = a + 1; b < 18; b++)
      for (let c = b + 1; c < 18; c++) {
        const sides = [a, b, c].map((s) => Math.floor(s / 3))
        if (sides[0] === sides[1] || sides[1] === sides[2] || sides[0] === sides[2]) continue
        if (armAngle(a, b) < MIN_ANGLE || armAngle(b, c) < MIN_ANGLE || armAngle(a, c) < MIN_ANGLE) continue
        shapes.push({ cls: JUNCTION, sdf: armsSdf([a, b, c]), sides })
      }
  shapes.push({ cls: POCKET, sdf: (x, y) => Math.hypot(x, y) - 0.4 })

  /** @type {Tile[]} */
  const tiles = []
  const seen = new Set()
  for (const sh of shapes) {
    let sockets = 0
    for (let s = 0; s < 18; s++) if (sh.sdf(SOCKET[s][0], SOCKET[s][1]) < -1e-9) sockets |= 1 << s
    // a pocket has no open socket, like solid rock: keep it as its own tile (it's a different shape)
    const key = sh.cls === POCKET ? 'pocket' : sockets
    if (seen.has(key)) continue
    seen.add(key)
    tiles.push({ id: tiles.length, cls: sh.cls, sockets, sdf: sh.sdf, sides: sh.sides || [], angle: sh.angle ?? -1 })
  }
  return tiles
}

/** The 3 sockets of side k as a 3-bit code (bit j = segment j). @param {number} sockets @param {number} k */
export const sideCode = (sockets, k) => (sockets >>> (3 * k)) & 7

/** The code a neighbour must show on the facing side: the segment order reverses. @param {number} v */
export const reversed = (v) => ((v & 1) << 2) | (v & 2) | ((v >> 2) & 1)
